import 'dart:io';import 'package:cloud_firestore/cloud_firestore.dart';import 'package:firebase_auth/firebase_auth.dart';import 'package:forge/services/storage_service.dart';import '../models/app_user.dart';import '../models/character.dart';import 'user_service.dart';class AuthService {  AuthService({    FirebaseAuth? auth,    UserService? userService,  })  : _auth = auth ?? FirebaseAuth.instance,        _userService = userService ?? UserService();  final FirebaseAuth _auth;  final UserService _userService;  User? get currentUser => _auth.currentUser;  Stream<User?> get authStateChanges => _auth.authStateChanges();  String nicknameToEmail(String nickname) {    final normalized =        nickname.trim().toLowerCase().replaceAll(RegExp(r'\s+'), '_');    return '$normalized@forge.local';  }  Future<String> register({    required String nickname,    required String password,    required String firstName,    required String middleName,    required String lastName,    // required File uploadedImageUrl,    required String uploadedImageUrl,    required String slogan,    required List<String> abilitiesText,  }) async {    final trimmedNickname = nickname.trim();    if (trimmedNickname.isEmpty) {      throw FirebaseAuthException(        code: 'invalid-nickname',        message: 'Nickname cannot be empty.',      );    }    if (trimmedNickname.length < 3) {      throw FirebaseAuthException(        code: 'invalid-nickname',        message: 'Nickname must be at least 3 characters.',      );    }    final authEmail = nicknameToEmail(trimmedNickname);    final credential = EmailAuthProvider.credential(      email: authEmail,      password: password,    );    final user = _auth.currentUser;    UserCredential userCredential;    if (user != null && user.isAnonymous) {      userCredential = await user.linkWithCredential(credential);    } else if (user == null) {      userCredential = await _auth.createUserWithEmailAndPassword(        email: authEmail,        password: password,      );    } else {      throw FirebaseAuthException(        code: 'already-signed-in',        message: 'Sign out before creating a new account.',      );    }    final uid = userCredential.user!.uid;    final displayName = '$firstName $lastName'.trim();    await userCredential.user?.updateDisplayName(      displayName.isEmpty ? trimmedNickname : displayName,    );    final appUser = AppUser.newRegistration(      id: uid,      nickname: trimmedNickname,      firstName: firstName.trim(),      middleName: middleName.trim(),      lastName: lastName.trim(),      authEmail: authEmail,    );    // final url = await StorageService().uploadAvatar(    //   userId: uid,    //   image: uploadedImageUrl,    // );    final character = Character.newForRegistration(      userId: uid,      name: trimmedNickname,      slogan: slogan.trim(),      // avatarUrl: url,      avatarUrl: uploadedImageUrl,      abilitiesText: abilitiesText.join(' '),    );    await _userService.createUserWithCharacter(      user: appUser,      character: character,    );    return uid;  }  Future<void> login({    required String nickname,    required String password,  }) async {    final trimmedNickname = nickname.trim();    if (trimmedNickname.isEmpty) {      throw FirebaseAuthException(        code: 'invalid-nickname',        message: 'Nickname cannot be empty.',      );    }    final authEmail = nicknameToEmail(trimmedNickname);    if (_auth.currentUser != null) {      await _auth.signOut();    }    await _auth.signInWithEmailAndPassword(      email: authEmail,      password: password,    );  }  Stream<List<Character>> watchAllCharacters() {    return FirebaseFirestore.instance        .collection('characters')        .snapshots()        .map(          (snapshot) => snapshot.docs          .map((doc) => Character.fromFirestore(doc))          .toList(),    );  }  Future<AppUser?> getCurrentAppUser() async {    final uid = _auth.currentUser?.uid;    if (uid == null) return null;    return _userService.getUser(uid);  }  Stream<Character?> watchCurrentCharacter() {    final uid = _auth.currentUser?.uid;    if (uid == null) {      return Stream.value(null);    }    return _userService.watchCharacter(uid);  }  Stream<AppUser?> watchCurrentAppUser() {    final uid = _auth.currentUser?.uid;    if (uid == null) {      return Stream.value(null);    }    return _userService.watchUser(uid);  }  Future<void> signOut() async {    await _auth.signOut();  }}